/**
 * MandalaEmblem — the embossed-gold mandala at the heart of Home: an
 * eight-pointed filigree star around a sunken medallion holding an amber
 * crescent. It is also Home's Ask Shams button.
 *
 * The artwork is a pre-rendered transparent PNG (assets/images/home-mandala.png,
 * 960 × 960) generated by scripts/generate-home-mandala.py. Its carved-metal
 * relief comes from SVG lighting filters, which react-native-svg does not
 * implement, so the app shows the rendered image rather than drawing it live.
 * To change the artwork, edit that script and re-run it.
 *
 * Motion: a gentle entrance, a slow ambient glow and a very slow revolution
 * while idle. When pressed, the emblem spins and swells towards the viewer
 * while fading, as if lifting out of the screen, and only then calls
 * onPress. All of it is skipped when the user has asked the system to reduce
 * motion; onPress then fires straight away.
 *
 * With onPress it is a button (labelled by accessibilityLabel); without it,
 * it is purely decorative and hidden from screen readers.
 */

import React, { useCallback, useEffect, useRef, useState } from 'react';
import {
  AccessibilityInfo,
  Animated,
  Easing,
  Image,
  Pressable,
  StyleSheet,
  View,
} from 'react-native';
import Svg, { Circle, Defs, RadialGradient, Stop } from 'react-native-svg';

import { CELESTIAL } from './celestialPalette';

const MANDALA_IMAGE = require('@assets/images/home-mandala.png');

/** One idle revolution, in ms — slow enough to read as stillness that breathes. */
const IDLE_REVOLUTION_MS = 120000;
/** The press animation, in ms, before onPress fires. */
const LIFT_MS = 650;
/** How long after onPress the emblem settles back (hidden under the next screen). */
const RESET_DELAY_MS = 700;

interface MandalaEmblemProps {
  size?: number;
  testID?: string;
  onPress?: () => void;
  accessibilityLabel?: string;
}

const MandalaEmblem: React.FC<MandalaEmblemProps> = ({
  size = 280,
  testID = 'home-mandala',
  onPress,
  accessibilityLabel,
}) => {
  const appear = useRef(new Animated.Value(0)).current;
  const glow = useRef(new Animated.Value(0.55)).current;
  const idle = useRef(new Animated.Value(0)).current;
  const lift = useRef(new Animated.Value(0)).current;
  const lifting = useRef(false);
  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [reduceMotion, setReduceMotion] = useState(false);

  useEffect(() => {
    let cancelled = false;
    AccessibilityInfo.isReduceMotionEnabled()
      .then(v => {
        if (!cancelled) {
          setReduceMotion(v);
        }
      })
      .catch(() => undefined);
    return () => {
      cancelled = true;
      if (resetTimer.current !== null) {
        clearTimeout(resetTimer.current);
      }
    };
  }, []);

  useEffect(() => {
    if (reduceMotion) {
      appear.setValue(1);
      glow.setValue(0.8);
      idle.setValue(0);
      return undefined;
    }
    Animated.timing(appear, {
      toValue: 1,
      duration: 700,
      easing: Easing.out(Easing.cubic),
      useNativeDriver: true,
    }).start();
    const glowLoop = Animated.loop(
      Animated.sequence([
        Animated.timing(glow, {
          toValue: 1,
          duration: 3600,
          easing: Easing.inOut(Easing.sin),
          useNativeDriver: true,
        }),
        Animated.timing(glow, {
          toValue: 0.55,
          duration: 3600,
          easing: Easing.inOut(Easing.sin),
          useNativeDriver: true,
        }),
      ]),
    );
    const idleLoop = Animated.loop(
      Animated.timing(idle, {
        toValue: 1,
        duration: IDLE_REVOLUTION_MS,
        easing: Easing.linear,
        useNativeDriver: true,
      }),
    );
    glowLoop.start();
    idleLoop.start();
    return () => {
      glowLoop.stop();
      idleLoop.stop();
    };
  }, [appear, glow, idle, reduceMotion]);

  const handlePress = useCallback(() => {
    if (onPress === undefined || lifting.current) {
      return;
    }
    if (reduceMotion) {
      onPress();
      return;
    }
    lifting.current = true;
    Animated.timing(lift, {
      toValue: 1,
      duration: LIFT_MS,
      easing: Easing.in(Easing.cubic),
      useNativeDriver: true,
    }).start(() => {
      onPress();
      // Settle back once the next screen has covered Home.
      resetTimer.current = setTimeout(() => {
        lift.setValue(0);
        lifting.current = false;
      }, RESET_DELAY_MS);
    });
  }, [lift, onPress, reduceMotion]);

  const c = size / 2;
  // Idle turn (0..1) plus one and a half extra turns while lifting.
  const rotate = Animated.add(idle, Animated.multiply(lift, 1.5)).interpolate({
    inputRange: [0, 2.5],
    outputRange: ['0deg', '900deg'],
  });
  const scale = Animated.multiply(
    appear.interpolate({ inputRange: [0, 1], outputRange: [0.96, 1] }),
    lift.interpolate({ inputRange: [0, 1], outputRange: [1, 1.9] }),
  );
  const opacity = Animated.multiply(
    appear,
    lift.interpolate({ inputRange: [0, 0.6, 1], outputRange: [1, 0.9, 0] }),
  );

  const emblem = (
    <>
      {/* Slow warm glow behind the emblem */}
      <Animated.View pointerEvents="none" style={[StyleSheet.absoluteFill, { opacity: glow }]}>
        <Svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
          <Defs>
            <RadialGradient id="mandalaAura" cx="50%" cy="50%" rx="50%" ry="50%">
              <Stop offset="0%" stopColor={CELESTIAL.amber} stopOpacity={0.32} />
              <Stop offset="55%" stopColor={CELESTIAL.antiqueGold} stopOpacity={0.08} />
              <Stop offset="100%" stopColor={CELESTIAL.antiqueGold} stopOpacity={0} />
            </RadialGradient>
          </Defs>
          <Circle cx={c} cy={c} r={c} fill="url(#mandalaAura)" />
        </Svg>
      </Animated.View>

      <Animated.View style={{ opacity, transform: [{ scale }, { rotate }] }}>
        <Image
          source={MANDALA_IMAGE}
          style={{ width: size, height: size }}
          resizeMode="contain"
          fadeDuration={0}
        />
      </Animated.View>
    </>
  );

  if (onPress === undefined) {
    return (
      <View
        accessible={false}
        importantForAccessibility="no-hide-descendants"
        accessibilityElementsHidden
        testID={testID}
        style={{ width: size, height: size }}
      >
        {emblem}
      </View>
    );
  }

  return (
    <Pressable
      testID={testID}
      onPress={handlePress}
      style={{ width: size, height: size }}
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel}
    >
      {emblem}
    </Pressable>
  );
};

export default MandalaEmblem;
